import type { FighterArt } from '../types';
import { NAYO_CELLS } from './cells';
import { NAYO_CLIPS, NAYO_PROJECTILE } from './clips';
import { NAYO_SHEETS, type NayoSheet } from './sheets';

/** Strips generated by `npm run sprites` (tools/sprites), one folder per colorway. */
const MAIN = import.meta.glob<string>('./main/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT = import.meta.glob<string>('./alt/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
/** Front effects of the strips that have some (energy, flashes, speed lines). */
const MAIN_FX = import.meta.glob<string>('./main/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});
const ALT_FX = import.meta.glob<string>('./alt/fx/*.png', {
  eager: true,
  query: '?url',
  import: 'default',
});

/** URL of each strip found in a colorway folder; a missing one fails validation. */
function urlsOf(files: Readonly<Record<string, string>>, folder: string): Record<string, string> {
  const urls: Record<string, string> = {};
  for (const sheet of Object.keys(NAYO_SHEETS) as NayoSheet[]) {
    const url = files[`./${folder}/${sheet}.png`];
    if (url !== undefined) urls[sheet] = url;
  }
  return urls;
}

const SHARED = {
  sheets: NAYO_SHEETS,
  clips: NAYO_CLIPS,
  projectile: NAYO_PROJECTILE,
  cells: NAYO_CELLS,
};

/** Black techwear, cyan neon. */
export const NAYO: FighterArt = {
  key: 'nayo',
  urls: urlsOf(MAIN, 'main'),
  fx: urlsOf(MAIN_FX, 'main/fx'),
  ...SHARED,
};
/** Light grey techwear, magenta neon: player 2 in a mirror match. */
export const NAYO_ALT: FighterArt = {
  key: 'nayo-alt',
  urls: urlsOf(ALT, 'alt'),
  fx: urlsOf(ALT_FX, 'alt/fx'),
  ...SHARED,
};
